=== file: main.loom ===
budget { tokens: 100000 calls: 1000 }

provider InternalClassifier {
    use: jev
    api_key: env.JEV_API_KEY
}

intentclassifier TicketClassification {
    model: "InternalClassifier/jev-latest"
    choose product_area: AREA_A | AREA_B | AREA_C
    choose priority: PRIORITY_A | PRIORITY_B | PRIORITY_C
    confidence at least 0.8 else escalate
}

tool RedactTicketContent {
    use: class
    class: com.acme.RedactTicketContent
}

tool StandupCsv {
    use: file
    root: "standup"
    mode: write
}

workflow Main(ticket_record) {
    human_prompt "Workflow Owner: provide the shared folder path, stand-up time and local time zone, approved product-area and priority labels, and confirm the Jev-backed classification service and model are approved for internal use." -> activation_requirements_confirmation
    halt "Activation remains blocked pending configuration and review. Workflow Owner response: {activation_requirements_confirmation}"
}
=== end ===
=== file: tests/main.test.yaml ===
script: ../main.loom
workflow: Main
cases:
  - name: configuration is required before processing
    input: { ticket_record: "The application is not working" }
    humans: ["Configuration details are not yet available."]
    expect: { final: halted }
=== end ===
